(()=>{
const host=document.querySelector('[data-schedule-root]')||document;
const $=s=>host.querySelector(s), form=$('#lesson-form'), filters=$('#filters');
let listGeneration=0,showFullDay=false,studentRangeMode='auto';
try{if(localStorage.getItem('krug-pi-student-calendar-range')==='fixed')studentRangeMode='fixed'}catch{}
let config, students=[],editing=null,offset=0,weekStart,busy=false,calendarGeneration=0,calendarCleanup=null,calendarDuration=null,secondaryZone='Europe/Berlin';
const states={scheduled:'Запланировано',completed:'Проведено',cancelled:'Отменено'};
function plus(date,n){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function localInput(value){const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:config.timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value));return parts.replace(' ','T')}
function text(tag,value){const e=document.createElement(tag);e.textContent=value;return e}
function money(value){return (value/100).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₽'}
async function api(path='',method='GET',data){if(method==='GET'&&config?.role==='admin'&&path.startsWith('?'))path+='&display_timezone='+encodeURIComponent(config.timezone);const response=await fetch('/api/lessons'+path,{method,cache:'no-store',headers:method==='GET'?{}:{'Content-Type':'application/json','X-Requested-With':'KrugPi'},...(data?{body:JSON.stringify(data)}:{})});const result=await response.json();if(!response.ok)throw Error(typeof result.detail==='string'?result.detail:response.status===401?'Войдите в личный кабинет.':'Проверьте заполнение полей.');return result}
function scopeFor(row){if(!row.series_id)return 'one';const choice=prompt('Область изменения: 1 — только этот урок; 2 — этот и следующие; 3 — все будущие уроки серии','1');return {'1':'one','2':'following','3':'series'}[choice]}
function card(row,actions=true){const e=text('article','');e.className='lesson-card '+row.status;e.append(text('strong',new Date(row.starts_at).toLocaleString('ru-RU',{timeZone:config.timezone,dateStyle:'short',timeStyle:'short'})));if(config.role==='admin'){e.append(text('h3',row.student_name));if(row.student_timezone)e.append(text('p','У ученика ('+row.student_timezone+'): '+new Date(row.starts_at).toLocaleString('ru-RU',{timeZone:row.student_timezone,dateStyle:'short',timeStyle:'short'})));}if(row.series_id)e.append(text('p','Постоянное время серии: '+row.timezone));if(row.status==='completed'){const materialLink=text('a','Задание и конспект');materialLink.href='materials.html?lesson_id='+row.id+'&student_id='+row.student_id;e.append(materialLink)}e.append(text('p',states[row.status]+' · '+row.duration_minutes+' мин · '+money(row.price_kopecks)));if(row.topic)e.append(text('p',row.topic));if(row.series_id)e.append(text('small','Повторяющееся занятие'));if(row.meeting_url&&row.status==='scheduled'){const a=text('a','Открыть онлайн-урок →');a.href=row.meeting_url;a.target='_blank';a.rel='noopener noreferrer';e.append(text('p',''),a)}if(config.role==='admin'&&actions&&row.status!=='completed'){const controls=text('div','');controls.className='lesson-actions';for(const [label,handler] of [['Изменить',()=>openEditor(row)],[row.status==='cancelled'?'Восстановить урок':'Отменить урок',()=>changeStatus(row,row.status==='cancelled'?'scheduled':'cancelled')],['Проведено',()=>changeStatus(row,'completed')],['Удалить',()=>remove(row)]]){const b=text('button',label);b.type='button';b.onclick=handler;controls.append(b)}e.append(controls)}return e}
function defaults(){const student=students.find(s=>s.id===Number(form.elements.student_id.value));if(student){form.elements.duration_minutes.value=calendarDuration??student.default_duration_minutes;form.elements.price.value=(student.default_price_kopecks/100).toFixed(2)}updateEditorTimeHint()}
function openEditor(row=null){calendarDuration=null;editing=row;form.reset();form.querySelector('[type=submit]').disabled=false;$('#form-status').textContent='';$('#editor').hidden=false;$('#primary-zone').disabled=true;$('#editor-title').textContent=row?'Изменить занятие':'Новое занятие';$('#recurrence').hidden=!!row;$('#edit-scope').hidden=!row?.series_id;form.elements.scope.value='one';if(row){if(!students.some(s=>s.id===row.student_id)){ form.querySelector('[type=submit]').disabled=true;$('#form-status').textContent='Ученик архивирован. Для переноса сначала восстановите его в кабинете администратора.';return;}for(const field of ['student_id','duration_minutes','topic','meeting_url'])form.elements[field].value=row[field];form.elements.starts_at.value=localInput(row.starts_at);form.elements.price.value=(row.price_kopecks/100).toFixed(2)}else{defaults();form.elements.starts_at.value=config.today+'T12:00'}updateEditorTimeHint();$('#editor').scrollIntoView({block:'start'});form.elements.student_id.focus()}
async function mutate(action){if(busy)return;busy=true;try{await action();$('#status').textContent='Изменения сохранены';await refresh()}catch(e){$('#status').textContent=e.message}finally{busy=false}}
async function changeStatus(row,status){if(status==='cancelled'){openCancellation(row);return}const scope=status==='completed'?'one':scopeFor(row);if(!scope||!confirm('Изменить статус: '+states[status]+'?'))return;await mutate(()=>api('/'+row.id+'/status','PATCH',{status,scope}))}
function openCancellation(row){
 if(busy)return;
 const dialog=text('dialog','');dialog.className='lesson-cancel-dialog';const title=text('h2','Отменить урок');title.id='lesson-cancel-title';dialog.setAttribute('aria-labelledby',title.id);
 const when=new Date(row.starts_at).toLocaleString('ru-RU',{timeZone:config.timezone,dateStyle:'long',timeStyle:'short'});
 const summary=text('p',row.student_name+' · '+when+' · '+config.timezone),help=text('p','Отменённый урок сохранится в календаре и истории. Деньги за него не списываются.'),cancelForm=text('form',''),label=text('label','Какие занятия отменить?'),select=text('select','');
 for(const [value,name] of [['one','Только этот урок'],...(row.series_id?[['following','Этот и следующие будущие уроки серии'],['series','Все будущие уроки серии']]:[])]){const option=text('option',name);option.value=value;select.append(option)}label.append(select);
 const feedback=text('p','');feedback.setAttribute('role','status');const actions=text('div','');actions.className='lesson-actions';const submit=text('button','Отменить урок'),back=text('button','Оставить занятие');submit.type='submit';back.type='button';back.onclick=()=>dialog.close();actions.append(submit,back);cancelForm.append(label,feedback,actions);dialog.append(title,summary,help,cancelForm);host===document?document.body.append(dialog):host.append(dialog);
 let saving=false;dialog.addEventListener('cancel',event=>{if(saving)event.preventDefault()});dialog.addEventListener('close',()=>dialog.remove());
 cancelForm.onsubmit=async event=>{event.preventDefault();if(saving||busy)return;saving=true;busy=true;submit.disabled=back.disabled=select.disabled=true;feedback.textContent='Отменяем…';try{const result=await api('/'+row.id+'/status','PATCH',{status:'cancelled',scope:select.value});dialog.close();$('#status').textContent='Отменено занятий: '+result.updated+'. Баланс не списывается.';try{await refresh()}catch{$('#status').textContent='Отмена сохранена. Нажмите «Обновить», чтобы увидеть изменения.'}}catch(e){feedback.textContent=e.message}finally{saving=false;busy=false;submit.disabled=back.disabled=select.disabled=false}};
 dialog.showModal();back.focus();
}
async function remove(row){const scope=scopeFor(row);if(!scope||!confirm('Удалить выбранные будущие занятия? Для сохранения истории используйте отмену.'))return;await mutate(()=>api('/'+row.id+'?scope='+scope,'DELETE'))}
function updateEditorTimeHint(){if(!config)return;$('#editor-zone').textContent='Дата и время формы: '+config.timezone;const value=form.elements.starts_at.value,duration=Number(form.elements.duration_minutes.value);if(!value){$('#secondary-preview').textContent='';return}const [day,time]=value.split('T'),[hour,minute]=time.split(':').map(Number),times=WeeklyCalendar.instants(day,hour*60+minute,config.timezone);if(times.length!==1){$('#secondary-preview').textContent='Это местное время отсутствует или неоднозначно из-за перевода часов.';return}const student=students.find(s=>s.id===Number(form.elements.student_id.value)),studentZone=student?.timezone||config.student_default_timezone||config.timezone;const lines=[];for(const [name,tz] of [['У ученика',studentZone],['Второй пояс',secondaryZone]]){if(!tz)continue;const label=new Intl.DateTimeFormat('ru-RU',{timeZone:tz,dateStyle:'short',timeStyle:'short'});lines.push(name+' ('+tz+'): '+label.format(times[0])+(Number.isFinite(duration)&&duration>0?' — '+label.format(times[0]+duration*60000):''))}$('#secondary-preview').textContent=lines.join(' · ');const seriesZone=form.elements.recurrence_timezone.value==='student'?studentZone:config.timezone;$('#recurrence-zone-hint').textContent='Дни недели и конец серии: '+seriesZone+'. Первое занятие в этом поясе: '+new Intl.DateTimeFormat('ru-RU',{timeZone:seriesZone,dateStyle:'full',timeStyle:'short'}).format(times[0]);}
form.elements.recurrence_timezone.onchange=updateEditorTimeHint;
form.elements.student_id.onchange=defaults;
form.elements.starts_at.oninput=updateEditorTimeHint;
form.elements.duration_minutes.oninput=()=>{if(!editing)calendarDuration=Number(form.elements.duration_minutes.value);updateEditorTimeHint()};
function validZone(value){try{new Intl.DateTimeFormat('ru-RU',{timeZone:value});return !!value}catch{return false}}
function setupPrimaryZone(){const picker=$('#primary-zone'),names={'Europe/Berlin':'Берлин','Europe/Moscow':'Москва','Europe/London':'Лондон','Asia/Vladivostok':'Владивосток','Asia/Yekaterinburg':'Екатеринбург','UTC':'UTC'};let saved;try{saved=localStorage.getItem('krug-pi-primary-zone')}catch{}if(validZone(saved))config.timezone=saved;const zones=new Set([config.timezone,'Europe/Berlin','Europe/Moscow','Europe/London','Asia/Vladivostok','UTC',...(Intl.supportedValuesOf?Intl.supportedValuesOf('timeZone'):[])]);for(const zone of [...zones].sort()){const option=text('option',names[zone]?names[zone]+' ('+zone+')':zone);option.value=zone;picker.append(option)}picker.value=config.timezone;$('#primary-zone-control').hidden=false;config.today=WeeklyCalendar.local(new Date(),config.timezone).day;$('#zone').textContent='Все даты и время: '+config.timezone;currentWeek();}
$('#primary-zone').onchange=async()=>{const picker=$('#primary-zone'),previous=config.timezone,next=picker.value;if(!validZone(next)){picker.value=previous;return}config.timezone=next;config.today=WeeklyCalendar.local(new Date(),next).day;try{localStorage.setItem('krug-pi-primary-zone',next)}catch{}if(secondaryZone===next){secondaryZone=['','Europe/Berlin','Europe/Moscow','Europe/London','UTC'].includes(previous)?previous:'';$('#secondary-zone').value=secondaryZone;try{localStorage.setItem('krug-pi-secondary-zone',secondaryZone)}catch{}}$('#zone').textContent='Все даты и время: '+next;offset=0;listGeneration++;calendarGeneration++;picker.disabled=true;$('#status').textContent='Обновляем часовой пояс…';try{await refresh();$('#status').textContent='Часовой пояс изменён. Выбор сохранён в этом браузере.'}catch(e){$('#status').textContent=e.message}finally{picker.disabled=false}};
$('#secondary-zone').onchange=()=>{secondaryZone=$('#secondary-zone').value;try{localStorage.setItem('krug-pi-secondary-zone',secondaryZone)}catch{}updateEditorTimeHint();void calendar().catch(e=>$('#status').textContent=e.message)};
form.onsubmit=async event=>{event.preventDefault();const price=form.elements.price.value.replace(',','.');if(!/^\d+(\.\d{1,2})?$/.test(price)){ $('#form-status').textContent='Введите цену с точностью до копеек';return}const [rub,kop='']=price.split('.');const data={student_id:Number(form.elements.student_id.value),starts_at:form.elements.starts_at.value,timezone:config.timezone,duration_minutes:Number(form.elements.duration_minutes.value),price_kopecks:Number(rub)*100+Number(kop.padEnd(2,'0')),topic:form.elements.topic.value,meeting_url:form.elements.meeting_url.value};if(editing){data.scope=form.elements.scope.value;const [day,time]=data.starts_at.split('T'),[h,m]=time.split(':').map(Number),instants=WeeklyCalendar.instants(day,h*60+m,config.timezone);if(instants.length!==1){$('#form-status').textContent='Выберите однозначное местное время';return}data.starts_at=new Date(instants[0]).toISOString();data.timezone=editing.timezone;}else{data.recurrence_timezone=form.elements.recurrence_timezone.value;data.weekdays=[...form.querySelectorAll('[name=weekday]:checked')].map(e=>Number(e.value));data.recurrence_end=form.elements.recurrence_end.value||null}const button=form.querySelector('[type=submit]');button.disabled=true;try{const result=await api(editing?'/'+editing.id:'',editing?'PUT':'POST',data);$('#editor').hidden=true;$('#primary-zone').disabled=false;$('#status').textContent=editing?'Занятия обновлены':'Создано занятий: '+result.count;await refresh()}catch(e){$('#form-status').textContent=e.message}finally{button.disabled=false}};
function showCalendarLesson(row){const panel=$('#selected-lesson');panel.replaceChildren();const close=text('button','Закрыть');close.type='button';close.onclick=()=>panel.hidden=true;panel.append(text('h2','Занятие'),close,card(row));panel.hidden=false;panel.scrollIntoView({block:'nearest'});panel.focus()}
function createFromCalendar(value,duration){if(!students.length){$('#status').textContent='Сначала добавьте активного ученика в кабинете администратора.';return}openEditor();form.elements.starts_at.value=value;if(duration!==undefined){calendarDuration=duration;form.elements.duration_minutes.value=duration}updateEditorTimeHint();form.elements.starts_at.focus()}
async function calendar(){
 const generation=++calendarGeneration,requestedWeek=weekStart,end=plus(requestedWeek,7),root=$('#calendar');
 $('#week-label').textContent=new Date(requestedWeek+'T12:00:00Z').toLocaleDateString('ru-RU',{timeZone:'UTC',day:'numeric',month:'long'})+' — '+new Date(plus(requestedWeek,6)+'T12:00:00Z').toLocaleDateString('ru-RU',{timeZone:'UTC',day:'numeric',month:'long',year:'numeric'});
 root.setAttribute('aria-busy','true');root.inert=true;
 try{const rows=[];let start=0,total=0;do{const data=await api('?'+new URLSearchParams({from_date:requestedWeek,to_date:end,limit:100,offset:start,overlap:true}));if(generation!==calendarGeneration)return;rows.push(...data.items);total=data.total;start+=100}while(start<total);
 if(calendarCleanup){calendarCleanup();calendarCleanup=null}
 $('#selected-lesson').hidden=true;

 const visibleRows=rows;
 const {startMinute,endMinute}=config.role==='student'?(WeeklyCalendar.studentWindow('lessons',rows,requestedWeek,config.timezone)||{startMinute:0,endMinute:1440}):showFullDay?{startMinute:0,endMinute:1440}:WeeklyCalendar.adminWindow(rows,requestedWeek,config.timezone);
 host.querySelectorAll('#calendar-legend .completed,#calendar-legend .cancelled').forEach(item=>item.hidden=false);
 $('#day-range').hidden=config.role==='student';$('#range-label').textContent='Диапазон: '+String(Math.floor(startMinute/60)).padStart(2,'0')+':'+String(startMinute%60).padStart(2,'0')+'–'+String(Math.floor(endMinute/60)).padStart(2,'0')+':'+String(endMinute%60).padStart(2,'0')+' · '+config.timezone;
 if(config.role==='student'&&!WeeklyCalendar.studentWindow('lessons',rows,requestedWeek,config.timezone)){$('#range-label').textContent='';root.replaceChildren(text('p','На этой неделе занятий пока нет.'));return}
 calendarCleanup=WeeklyCalendar.render(root,visibleRows,{startMinute,endMinute,weekStart:requestedWeek,timezone:config.timezone,secondaryZone:config.role==='student'?'':secondaryZone,readOnly:config.role==='student',onCreate:createFromCalendar,onOpen:showCalendarLesson,onInvalid:message=>$('#status').textContent=message});
 }catch(e){if(generation===calendarGeneration){if(calendarCleanup)calendarCleanup();calendarCleanup=null;root.replaceChildren(text('p','Не удалось загрузить календарь. Нажмите «Обновить».'))}throw e}
 finally{if(generation===calendarGeneration){root.inert=false;root.setAttribute('aria-busy','false')}}
}
async function list(){if(host.dataset?.overview&&host.dataset.scheduleView!=='list')return;const generation=++listGeneration;const params=new URLSearchParams({limit:20,offset});if(filters.elements.from_date.value)params.set('from_date',filters.elements.from_date.value);if(filters.elements.to_date.value)params.set('to_date',plus(filters.elements.to_date.value,1));if(filters.elements.student_id.value)params.set('student_id',filters.elements.student_id.value);const data=await api('?'+params);if(generation!==listGeneration)return;$('#lessons-list').replaceChildren(...data.items.map(r=>card(r)));$('#list-count').textContent='Всего: '+data.total;if(!data.items.length)$('#lessons-list').append(text('p','В этом периоде занятий нет.'));$('#previous-page').disabled=offset===0;$('#next-page').disabled=offset+20>=data.total}
async function refresh(){await calendar();await list()}
function setScheduleView(view,load=true){host.dataset?host.dataset.scheduleView=view:document.documentElement.dataset.scheduleView=view;$('#weekly-view').hidden=view==='list';$('#lesson-history').hidden=view!=='list';host.querySelectorAll('[data-schedule-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.scheduleView===view)));if(view==='list'&&load)void list().catch(e=>$('#status').textContent=e.message)}
window.addEventListener('schedule-show-week',()=>{if(config?.role==='admin')setScheduleView('week',false)});
host.querySelectorAll('[data-schedule-view]').forEach(button=>button.onclick=()=>setScheduleView(button.dataset.scheduleView));
$('#add').onclick=()=>openEditor();$('#cancel').onclick=()=>{$('#editor').hidden=true;$('#primary-zone').disabled=false};$('#refresh').onclick=()=>refresh().catch(e=>$('#status').textContent=e.message);
filters.onsubmit=event=>{event.preventDefault();offset=0;list().catch(e=>$('#status').textContent=e.message)};
for(const [selector,delta] of [['#previous-week',-7],['#next-week',7]])$(selector).onclick=()=>{weekStart=plus(weekStart,delta);calendar().catch(e=>$('#status').textContent=e.message)};
function currentWeek(){weekStart=plus(config.today,-((new Date(config.today+'T12:00:00Z').getUTCDay()+6)%7))}
$('#student-range-control').onchange=()=>{studentRangeMode=$('[name=student_range]:checked').value;try{localStorage.setItem('krug-pi-student-calendar-range',studentRangeMode)}catch{}void calendar().catch(e=>$('#status').textContent=e.message)};
$('#day-range').onchange=()=>{showFullDay=$('[name=admin_day_range]:checked').value==='full';calendar().catch(e=>$('#status').textContent=e.message)};
$('#this-week').onclick=()=>{currentWeek();calendar().catch(e=>$('#status').textContent=e.message)};
$('#previous-page').onclick=()=>{offset=Math.max(0,offset-20);list().catch(e=>$('#status').textContent=e.message)};$('#next-page').onclick=()=>{offset+=20;list().catch(e=>$('#status').textContent=e.message)};
(async()=>{try{config=await api('/settings');$('#zone').textContent='Все даты и время: '+config.timezone;currentWeek();if(config.role==='admin'){if(host===document)window.mountAdminNavigation('calendar');setupPrimaryZone();secondaryZone=config.timezone==='Europe/Berlin'?'Europe/Moscow':'Europe/Berlin';const allowed=['','Europe/Berlin','Europe/Moscow','Europe/London','UTC'];try{const saved=localStorage.getItem('krug-pi-secondary-zone');if(saved!==null&&allowed.includes(saved)&&saved!==config.timezone)secondaryZone=saved}catch{}$('#secondary-zone').value=secondaryZone;$('#secondary-zone-control').hidden=false;$('#back').href='admin.html';$('#add').hidden=false;$('#student-filter').hidden=false;let start=0,total;do{const r=await fetch('/api/admin/students?limit=100&offset='+start);if(!r.ok)throw Error('Не удалось загрузить учеников');const d=await r.json();students.push(...d.items.filter(s=>s.is_active));total=d.total;start+=100}while(start<total);for(const student of students){for(const select of [form.elements.student_id,filters.elements.student_id]){const option=text('option',student.name+' ('+student.username+')');option.value=student.id;select.append(option)}}}else{window.mountStudentNavigation('calendar');$('#student-range-control').hidden=true;host.querySelectorAll('[name=student_range]').forEach(radio=>radio.checked=radio.value===studentRangeMode);secondaryZone='';$('#calendar-help').textContent='Нажмите на занятие, чтобы увидеть подробности, ссылку на урок и материалы. Время указано в вашем часовом поясе.';}$('#content').hidden=false;if(config.role==='admin')setScheduleView('week',false);else host.querySelector('.schedule-view-tabs').hidden=true;await refresh();$('#status').textContent='';if(host!==document){host.dataset.calendarReady='true';window.dispatchEvent(new Event('schedule-ready'))}else if(config.role==='admin'){requestAnimationFrame(()=>window.scrollTo({top:Math.max(0,$('#weekly-view').getBoundingClientRect().top+window.scrollY-24),behavior:'auto'}))}}catch(e){$('#status').textContent=e.message}})();

})();
